async function loadCards() {
  try {
    const response = await fetch(API_URL);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const cards = await response.json();
    renderCards(cards);
  } catch (error) {
    showError(error.message);
  }
}

